INSERT INTO posts (slug, title, summary, content, category_id, region, merchant_name, risk_level, tags, author_name, loss_amount, view_count, like_count, favorite_count, comment_count, created_at) VALUES
	('rent-deposit-not-refunded', '退租时房东以“墙面有划痕”为由扣光 5000 押金', '合同里没写正常损耗条款，房东拿放大镜找瑕疵，押金一分不退。', '事情经过：\n我在 XX 小区租了一年，退租当天房东带了三个人来验房，拿着手电筒照墙面，说有三处指甲盖大小的划痕，要整体重新刷墙，报价 4800，加上保洁 200，押金 5000 全扣。\n\n关键坑点：\n1. 合同只写了“房屋及设施完好退还押金”，没有约定正常使用损耗标准。\n2. 入住时没有做交房清单和拍照留证。\n3. 房东口头说“到时候好商量”，千万别信。\n\n我的处理：\n先报警，警察到场调解无果；随后向街道司法所申请人民调解，同时整理了入住时的照片和微信聊天记录，证明墙面原本就有瑕疵。最终调解退回 3800 元。\n\n给后来人的建议：\n入住当天一定逐间拍照录像，列交房清单双方签字；退租前自己先拍一遍；合同里写清“正常损耗不扣押金”。', 1, '杭州 · 拱墅区', '个人房东（XX花园3幢）', 'high', '押金,二房东,交房清单', '踩过坑的小周', 5000, 12840, 642, 388, 96, '2026-09-08 10:12:00'),
	('rent-agent-loan-trap', '中介诱导签“租金分期”，其实是小额贷款', '说好押一付一，结果签的是贷款合同，退租还要还违约金。', '某长租公寓中介推荐“租金分期，月付更轻松”，让我在一个 App 上做认证。后来才发现那是小额贷款，贷款一次性打给中介，我每月还的是贷款。\n\n后果：\n公司跑路后，房东没收到租金要收房，但贷款还得继续还，否则上征信。\n\n如何识别：\n- 让你下载陌生金融 App、人脸识别、授权征信的，一律拒绝。\n- 合同抬头不是房东本人、收款方是第三方公司的要警惕。\n- 要求你签两份合同（租赁合同 + 服务/分期合同）的，仔细看第二份。', 1, '北京 · 朝阳区', 'XX公寓（已跑路）', 'high', '租金贷,长租公寓,征信', '北漂第五年', 32000, 20311, 981, 702, 154, '2026-09-05 21:40:00'),
	('food-seafood-price', '海边大排档“时价海鲜”结账 3800，点菜前没给菜单', '一条鱼、四只蟹，结账时才知道是“时价”，报警后打折了事。', '旅游城市大排档常见套路：点菜时口头报价“很便宜”，结账按“时价”算，且称重不去水、不去绳。\n\n防坑：\n1. 点菜前要求看菜单并拍照，确认单价和计价单位（斤/只）。\n2. 要求当面称重、去绳去水，看着写单子并签字。\n3. 结账对不上直接打 12315 和 110。\n\n结果：报警后店家改口，最终付了 1200，仍明显偏高，但赶时间没继续追究。', 2, '三亚 · 第一市场周边', 'XX海鲜大排档', 'high', '时价,宰客,明码标价', '爱吃海鲜的猫', 2600, 15620, 733, 401, 88, '2026-09-07 12:05:00'),
	('food-prepaid-card', '健身房办卡 2 年送 1 年，三个月后门店关门', '预付卡套路：疯狂促销后跑路，会员群维权无门。', '销售说“周年庆最后三天”，办了两年的卡 5999，送一年私教。三个月后门店贴出“设备检修”，再没开过门。\n\n维权路径：\n1. 收集合同、付款记录、聊天记录。\n2. 到市场监管局投诉，并联合其他会员集体报案。\n3. 金额大、涉及人数多的可考虑以合同诈骗报案。\n\n提醒：预付卡消费尽量选小额、短期；优先选有资金存管的商家。', 2, '成都 · 高新区', 'XX健身（连锁）', 'high', '预付卡,跑路,健身', '健身小白', 5999, 18903, 856, 623, 132, '2026-09-03 09:30:00'),
	('travel-low-price-group', '999 元云南六日游，一半时间在购物店', '低价团本质是购物团，不消费导游就冷暴力、甩团。', '报名时承诺“纯玩无购物”，实际每天两三个购物点，翡翠、银器、乳胶。不买就被导游阴阳怪气，甚至以“车坏了”为由拖延。\n\n应对：\n- 报名前查旅行社资质和真实评价，低于成本的团费一定有猫腻。\n- 保留行程单、聊天记录，强制购物可投诉至文旅局 12345。\n- 导游强迫消费时录音录像。\n\n结果：投诉后旅行社退还部分团费。', 3, '云南 · 昆明-大理-丽江', 'XX国际旅行社', 'high', '低价团,强制购物,黑导游', '背包客阿May', 3200, 22140, 1102, 845, 201, '2026-09-06 16:20:00'),
	('travel-hotel-fake-photos', '酒店“海景房”打开窗是工地，平台图片严重不符', '图片是五年前的，实际房间发霉、隔音差，退订被拒。', '某平台预订“一线海景大床房”，入住发现窗户对着施工工地，房间有霉味。前台说“图片仅供参考”。\n\n处理：\n1. 现场拍照录像，与订单页面截图对比。\n2. 在平台内投诉并申请“到店无房/货不对板”赔付。\n3. 平台不作为可向 12315 投诉平台。\n\n最终平台补偿了首晚房费。', 3, '厦门 · 曾厝垵', 'XX海景酒店', 'medium', '货不对板,海景房,退订', '旅行中的鱼', 880, 9840, 402, 233, 57, '2026-09-02 19:15:00'),
	('job-training-loan', '应聘“UI 设计助理”被要求交 19800 培训费', '招聘是假，卖课是真，还引导办理培训贷。', '面试时说“零基础可培养”，通过后要求先参加内部培训，费用 19800，可从工资扣。签的却是贷款合同。\n\n识别要点：\n- 正规公司招聘不收费、不培训贷、不押证件。\n- 招聘信息写得“包就业、高薪、零基础”的，多留个心眼。\n- 已签的尽快停止还款并报警，保留合同和转账记录。', 4, '深圳 · 南山区', 'XX科技（培训贷）', 'high', '培训贷,虚假招聘,包就业', '转行的小林', 19800, 17655, 921, 664, 143, '2026-09-04 11:00:00'),
	('job-unpaid-intern', '实习三个月不给转正也不发工资，理由是“考核未通过”', '口头承诺转正，实际白嫖劳动力。', '入职时口头说实习期一个月、表现好就转正。三个月过去，公司以“考核未通过”为由辞退，且拒付实习工资。\n\n建议：\n- 任何用工都要签书面协议，明确薪资、工时。\n- 保留考勤、工作成果、聊天记录。\n- 可向劳动监察大队投诉或申请劳动仲裁（事实劳动关系同样受保护）。', 4, '广州 · 天河区', 'XX文化传媒', 'medium', '白嫖,实习,劳动仲裁', '刚毕业的阿哲', 9000, 8120, 366, 210, 49, '2026-08-30 14:30:00'),
	('shopping-fake-cosmetics', '直播间“专柜小样”是假货，用完烂脸', '低价大牌小样多为假货，售后直接拉黑。', '在某直播间买了“专柜拆盒小样”，价格只有专柜三折。用后过敏，找客服已被拉黑。\n\n维权：\n1. 保存直播回放、订单、聊天记录。\n2. 向平台投诉售假，要求“假一赔三”。\n3. 可向 12315 举报，必要时送检。\n\n提醒：远低于市场价的大牌小样，基本是假货。', 5, '网购', 'XX严选直播间', 'high', '假货,直播带货,化妆品', '敏感肌小雅', 560, 13440, 588, 349, 76, '2026-09-01 20:50:00'),
	('shopping-presale-never-ships', '预售衣服等 45 天，商家跑路链接失效', '预售模式卷款，维权时店铺已关闭。', '下单时显示“预售，45 天内发货”，到期不发货，联系客服无人应答，之后店铺下架所有商品。\n\n应对：\n- 预售超长、店铺新开、销量异常的谨慎下单。\n- 及时在平台申请退款并投诉，平台有先行赔付义务。\n- 保留订单截图，超时可向消协投诉。', 5, '网购', 'XX女装旗舰店', 'medium', '预售,跑路,退款', '爱买衣服的果果', 399, 7620, 301, 188, 41, '2026-08-28 10:25:00'),
	('education-refund-hard', '给孩子报的英语班退费，要扣 30%“手续费”', '合同藏霸王条款，退费层层设卡。', '机构单方面换老师、换校区，家长要求退费，机构称按合同要扣 30% 手续费，且需等三个月。\n\n要点：\n- “概不退费”“高额手续费”属格式条款，可主张无效。\n- 向教育局（学科类）/市场监管局投诉。\n- 培训机构一次性收费不得超过 3 个月或 60 课时（政策要求）。', 6, '南京 · 鼓楼区', 'XX少儿英语', 'medium', '退费难,霸王条款,教培', '两个娃的妈', 8600, 9310, 421, 276, 63, '2026-08-27 15:40:00'),
	('health-medical-beauty', '医美“0 元体验”后被推销 3 万套餐，脸还肿了', '低价引流 + 话术逼单，无资质操作。', '网上看到“0 元水光针体验”，到店后被几个顾问围着推销，最后刷了 3 万办套餐。术后脸部红肿，机构称“正常反应”。\n\n维权：\n1. 查机构是否有《医疗机构执业许可证》、医生是否有执业证。\n2. 保存术前术后照片、消费记录。\n3. 向卫健委、12315 投诉，必要时做医疗损害鉴定。', 7, '上海 · 静安区', 'XX医疗美容', 'high', '医美,逼单,无资质', '想变美的Anna', 30000, 16780, 792, 551, 118, '2026-08-31 13:10:00'),
	('health-oral-upsell', '补一颗牙被建议做四颗烤瓷冠，花了 1.2 万', '过度医疗，小问题大处理。', '牙疼去诊所，医生说旁边三颗也要处理，否则会出问题，最终做了四颗烤瓷冠。后来公立医院医生说其实只需补一颗。\n\n建议：\n- 重大治疗前多去一家公立医院咨询，货比三家。\n- 要求书面治疗方案和费用明细。\n- 保留病历、收费单，可向卫健委投诉过度医疗。', 7, '武汉 · 江汉区', 'XX口腔诊所', 'medium', '过度医疗,口腔,烤瓷冠', '牙疼的老王', 12000, 6450, 288, 197, 44, '2026-08-25 09:05:00'),
	('finance-loan-service-fee', '贷款中介收 8% 服务费，其实是银行能直接办的', '包装资料、收取高额中介费，甚至伪造流水。', '急需用钱找中介，对方称“内部渠道、包过”，收了 8% 服务费。后来发现该产品银行 App 就能申请，且中介帮我伪造了收入证明。\n\n风险：\n- 伪造资料涉嫌骗贷，可能承担法律责任。\n- 正规银行贷款不收取中介费。\n- 已交费的保留证据报警或投诉。', 8, '重庆 · 渝中区', 'XX金融服务', 'high', '贷款中介,服务费,伪造', '急用钱的阿强', 9600, 10230, 477, 322, 71, '2026-08-26 17:45:00'),
	('renovation-extra-cost', '装修合同 12 万，最后结算 19 万', '低价签单，施工中疯狂增项。', '装修公司报价 12 万“全包”，开工后水电、防水、拆墙不断加钱，最后 19 万，且材料与约定品牌不符。\n\n防坑：\n- 签合同前明确“总价包干”范围，增项需书面签字确认。\n- 材料写明品牌型号，验收留样。\n- 保留合同、报价单、聊天记录，可投诉或起诉。', 9, '西安 · 雁塔区', 'XX装饰公司', 'high', '增项,以次充好,装修', '装修踩坑记', 70000, 14200, 690, 512, 109, '2026-08-29 11:35:00'),
	('other-pet-shop-sick', '宠物店买的“健康布偶”一周后确诊猫瘟', '星期猫套路，售后不认账。', '买的时候活蹦乱跳，商家保证健康。第五天开始不吃不喝，确诊猫瘟，治疗花了几千，商家拒绝负责。\n\n提醒：\n- 购买时要求出示疫苗本、检疫证明，签健康协议。\n- 尽量选择可实地回访、支持 7 天健康保障的商家。\n- 保留交易记录，可向市场监管投诉或起诉。', 10, '长沙 · 岳麓区', 'XX宠物生活馆', 'high', '星期猫,宠物,猫瘟', '铲屎官小美', 6500, 8890, 402, 267, 58, '2026-08-24 18:00:00');
INSERT INTO comments (post_id, author_name, content, created_at) VALUES
	(1, '租房老司机', '交房清单一定要写！我上次也是没写，吃了大亏。', '2026-09-08 12:30:00'),
	(1, '法律小白', '正常损耗不扣押金有法律依据的，《民法典》第 710 条。', '2026-09-08 15:10:00'),
	(1, '杭州网友', '建议直接去街道人民调解，比打官司快多了。', '2026-09-09 09:20:00'),
	(2, '北漂十年', '租金贷太坑了，我朋友现在还在还。', '2026-09-06 08:40:00'),
	(2, '金融民工', '记住：让你签金融合同的租赁都是耍流氓。', '2026-09-06 20:15:00'),
	(3, '旅游达人', '三亚吃海鲜一定去第一市场自己买再加工。', '2026-09-07 18:00:00'),
	(5, '云南本地人', '低于 2000 的云南六日游想都别想。', '2026-09-07 10:05:00'),
	(5, '导游圈外人', '纯玩团成本摆在那，天上不会掉馅饼。', '2026-09-08 11:30:00'),
	(7, '程序员转行', '培训贷报警真的有用，我成功解约了。', '2026-09-04 22:10:00'),
	(12, '医美避雷', '查资质！卫健委官网能查到执业许可。', '2026-09-01 09:45:00'),
	(15, '装修过来人', '增项一定要白纸黑字签字，口头都是坑。', '2026-08-30 14:20:00');
INSERT INTO guides (slug, title, scenario, category_id, summary, risk_level, steps, channels, legal_basis, script, created_at) VALUES
	('rent-deposit', '租房押金被无故克扣，如何要回来？', '退租时房东以各种理由扣押金、不退押金。', 1, '先协商、再调解、后投诉/诉讼，关键是证据链和“正常损耗”认定。', 'high',
